// DeveloperConsole.js
import React, { useState } from "react";
import './DeveloperConsole.css';

const DeveloperConsole = ({ closeConsole, openChatbot, config = {} }) => {

  const projectName = window.location.hostname
  .replace(/^www\./, "")
  .toLowerCase();

const DEFAULT_CONFIG = {
  API_BASE_URL: "https://api.genaitechsol.shop",
  PROJECT_NAME: projectName
};

  const FINAL_CONFIG = { ...DEFAULT_CONFIG, ...config };
  const [documents, setDocuments] = useState([]);
  const [metadataFile, setMetadataFile] = useState(null);
  const [metadataStats, setMetadataStats] = useState(null);
  const [metadataError, setMetadataError] = useState("");
  const [urls, setUrls] = useState([""]);
  const [chunkSize, setChunkSize] = useState(1500);
  const [chunkOverlap, setChunkOverlap] = useState(500);
  const [selectedEmbeddingModel, setSelectedEmbeddingModel] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [isPreprocessed, setIsPreprocessed] = useState(false);
  const [selectedVectorDB, setSelectedVectorDB] = useState("");
  const [selectedChatModel, setSelectedChatModel] = useState("");
  const [customPrompt, setCustomPrompt] = useState("");
  const [maxOutputTokens, setMaxOutputTokens] = useState(1024);
  const [notification, setNotification] = useState("");
  const [chatbotTitle, setChatbotTitle] = useState(config.BOT_NAME || "AUra✦");
  const [initialBotMessage, setInitialBotMessage] = useState("Hello! 👋 How can I help you today?");
  const [topK, setTopK] = useState(8);
  const [temperature, setTemperature] = useState(0.3);
  // NEW: quick questions shown as clickable buttons in the chat widget
  const [quickQuestions, setQuickQuestions] = useState([""]);
  
  const embeddingModels = [
    "all-MiniLM-L6-v2",
    "paraphrase-MiniLM-L6-v2",
    "distilbert-base-nli-stsb-mean-tokens",
    "all-distilroberta-v1",
    "paraphrase-distilroberta-base-v1",
    "stsb-roberta-base",
  ];

  const vectorDBs = ["Chroma", "FAISS", "Pinecone", "Weaviate", "Qdrant"];

  const chatModels = [
    "Qwen/QwQ-32B-Preview",
    "meta-llama/Llama-3.3-70B-Instruct-Turbo",
    "meta-llama/Meta-Llama-3.1-405B-Instruct-Turbo",
    "scb10x/scb10x-llama3-typhoon-v1-5-8b-instruct",
    "meta-llama/Meta-Llama-3.1-8B-Instruct-Turbo",
    "OpenAI/ChatGPT",
    "Google/Gemini",
    "llama3-8b-8192",
    "llama3-70b-8192",
    "llama-3.3-70b-versatile",
    "openai/gpt-oss-120b"
  ];

  const showTemporaryMessage = (msg, duration = 3000) => {
    setNotification(msg);
    setTimeout(() => setNotification(""), duration);
  };

  const handleDocumentUpload = (event) => {
    const files = event.target.files ? Array.from(event.target.files) : [];
    setDocuments((prev) => [...prev, ...files]);
  };

  const handleMetadataUpload = async (event) => {
  const file = event.target.files?.[0];

  setMetadataFile(null);
  setMetadataStats(null);
  setMetadataError("");

  if (!file) return;

  if (!file.name.toLowerCase().endsWith(".json")) {
    setMetadataError("Please upload a valid .json file.");
    event.target.value = "";
    return;
  }

  try {
    const content = await file.text();
    const metadata = JSON.parse(content);

    if (!Array.isArray(metadata) || metadata.length === 0) {
      throw new Error(
        "Metadata JSON must contain a non-empty array of URL records."
      );
    }

    const products = new Set();
    const uniqueUrls = new Set();

    for (let i = 0; i < metadata.length; i++) {
      const entry = metadata[i];

      if (
        !entry ||
        typeof entry !== "object" ||
        Array.isArray(entry) ||
        typeof entry.url !== "string" ||
        !entry.url.trim() ||
        !["main", "campaign", "blogs"].includes(entry.category) ||
        !Array.isArray(entry.product) ||
        !entry.product.every(
          (product) =>
            typeof product === "string" && product.trim().length > 0
        ) ||
        typeof entry.summary !== "string"
      ) {
        throw new Error(
          `Invalid metadata structure at record ${i + 1}.`
        );
      }

      const normalizedUrl = entry.url.trim();

      if (uniqueUrls.has(normalizedUrl)) {
        throw new Error(
          `Duplicate URL found at record ${i + 1}: ${normalizedUrl}`
        );
      }

      uniqueUrls.add(normalizedUrl);

      entry.product.forEach((product) => {
        products.add(product.trim());
      });
    }

    if (products.size === 0) {
      throw new Error(
        "The metadata JSON does not contain any supported products."
      );
    }

    setMetadataFile(file);

    setMetadataStats({
      totalUrls: uniqueUrls.size,
      totalProducts: products.size,
      categories: {
        main: metadata.filter((entry) => entry.category === "main").length,
        campaign: metadata.filter((entry) => entry.category === "campaign").length,
        blogs: metadata.filter((entry) => entry.category === "blogs").length,
      },
    });

    showTemporaryMessage("Metadata JSON validated successfully.");
  } catch (error) {
    setMetadataError(error.message || "Invalid metadata JSON.");
    event.target.value = "";
  }
};

  const removeDocument = (index) => {
    setDocuments((prev) => prev.filter((_, i) => i !== index));
  };

  const handleUrlChange = (index, value) => {
    const newUrls = [...urls];
    newUrls[index] = value;
    setUrls(newUrls);
  };

  const removeUrl = (index) => {
    setUrls((prev) => prev.filter((_, i) => i !== index));
  };

  const addUrlField = () => setUrls([...urls, ""]);

  // NEW: handlers for the quick-question boxes (same pattern as the URL fields)
  const handleQuickQuestionChange = (index, value) => {
    const updated = [...quickQuestions];
    updated[index] = value;
    setQuickQuestions(updated);
  };

  const removeQuickQuestion = (index) => {
    setQuickQuestions((prev) => prev.filter((_, i) => i !== index));
  };

  const addQuickQuestionField = () => setQuickQuestions([...quickQuestions, ""]);

  const handlePreprocessing = async () => {
    if (!selectedEmbeddingModel) {
      showTemporaryMessage("Please select an embedding model.");
      return;
    }
      if (metadataError) {
        showTemporaryMessage(
          "Please resolve the metadata JSON validation error."
        );
        return;
      }

      if (metadataFile && documents.length === 0) {
        showTemporaryMessage(
          "Please upload a PDF/DOCX containing the source content."
        );
        return;
      }

      if (
        documents.length === 0 &&
        !urls.some((url) => url.trim() !== "")
      ) {
        showTemporaryMessage(
          "Please upload documents or provide at least one URL."
        );
        return;
      }

    setIsProcessing(true);

    const formData = new FormData();
    formData.append("project_name", FINAL_CONFIG.PROJECT_NAME);
    documents.forEach((doc) => formData.append("doc_files", doc));
    if (metadataFile) {
      formData.append("metadata_file", metadataFile, metadataFile.name);
    }
    formData.append("links", JSON.stringify(urls.filter((url) => url.trim() !== "")));
    formData.append("embedding_model", selectedEmbeddingModel);
    formData.append("chunk_size", String(chunkSize));
    formData.append("chunk_overlap", String(chunkOverlap));

    try {
      const response = await fetch(`${FINAL_CONFIG.API_BASE_URL}/preprocess`, {
        method: "POST",
        body: formData,
      });

      const result = await response.json();

      if (response.ok || result.status === "success") {
        setIsPreprocessed(true);
        showTemporaryMessage("✅ Preprocessing completed successfully!");
      } else {
        throw new Error(result.detail || "Preprocessing failed");
      }
    } catch (error) {
      console.error("❌ Preprocessing error:", error);
      showTemporaryMessage(
        `❌ ${error.message || "Preprocessing failed. Please try again."}`,
        8000
      );
    } finally {
      setIsProcessing(false);
    }
  };

  const handleFinalConfiguration = async () => {
    if (!selectedVectorDB || !selectedChatModel) {
      showTemporaryMessage("Please select both vector database and chat model.");
      return;
    }

    try {
      const vectordbResponse = await fetch(`${FINAL_CONFIG.API_BASE_URL}/select_vectordb`, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({ vectordb: selectedVectorDB }),
      });

      if (!vectordbResponse.ok) throw new Error("Vector database selection failed.");
      await vectordbResponse.json();

      const formData = new FormData();
      formData.append("custom_prompt", customPrompt);
      formData.append("chatbot_title", chatbotTitle.trim());
      formData.append("initial_message", initialBotMessage.trim());
      formData.append("chat_model", selectedChatModel);
      formData.append("project_name", FINAL_CONFIG.PROJECT_NAME);
      formData.append("max_output_tokens", String(maxOutputTokens));
      formData.append("top_k", String(topK));
      formData.append("temperature", String(temperature));
      // NEW: send the non-empty quick questions as a JSON array
      formData.append(
        "quick_questions",
        JSON.stringify(quickQuestions.filter((q) => q.trim() !== ""))
      );

      const chatModelResponse = await fetch(`${FINAL_CONFIG.API_BASE_URL}/select_chat_model`, {
        method: "POST",
        body: formData,
      });

      if (!chatModelResponse.ok) throw new Error("Chat model selection failed.");
      await chatModelResponse.json();

      showTemporaryMessage("✅ Chatbot is ready!");
      setTimeout(() => {
        if (typeof closeConsole === "function") closeConsole();
        if (typeof openChatbot === "function") openChatbot();
      }, 500);

    } catch (error) {
      console.error("Error:", error);
      showTemporaryMessage("❌ Error in configuration. Please try again.");
    }
  };

  return (
    <div className="developer-console">
      <h2>Developer Console</h2>
      {!isPreprocessed && (
        <>
          <div className="section">
            <label>Upload Documents (PDF/DOCX):</label>
            <input type="file" multiple accept=".pdf,.docx" onChange={handleDocumentUpload} />
            <ul>
              {documents.map((doc, index) => (
                <li key={index}>
                  {doc.name}
                  <button className="remove-btn" onClick={() => removeDocument(index)}>❌</button>
                </li>
              ))}
            </ul>
          </div>

          <div className="section">
            <h3>Product Metadata (JSON)</h3>

            <p>
              Upload a metadata JSON file to enable product-aware
              retrieval, product validation, and intelligent URL selection.
            </p>

            <input
              type="file"
              accept=".json,application/json"
              onChange={handleMetadataUpload}
              disabled={isProcessing}
            />

            {metadataFile && metadataStats && (
              <div
                style={{
                  marginTop: "12px",
                  padding: "14px",
                  borderRadius: "8px",
                  border: "1px solid #ccc",
                }}
              >
                <p>
                  <strong>File:</strong> {metadataFile.name}
                </p>

                <p>
                  <strong>Total URLs:</strong> {metadataStats.totalUrls}
                </p>

                <p>
                  <strong>Distinct Products:</strong> {metadataStats.totalProducts}
                </p>

                <p>
                  <strong>Main Pages:</strong> {metadataStats.categories.main}
                </p>

                <p>
                  <strong>Campaign Pages:</strong> {metadataStats.categories.campaign}
                </p>

                <p>
                  <strong>Blog Pages:</strong> {metadataStats.categories.blogs}
                </p>

                <button
                  type="button"
                  className="remove-btn"
                  onClick={() => {
                    setMetadataFile(null);
                    setMetadataStats(null);
                    setMetadataError("");
                  }}
                >
                  Remove Metadata
                </button>
              </div>
            )}

            {metadataError && (
              <p style={{ color: "#e53935", marginTop: "10px" }}>
                {metadataError}
              </p>
            )}

            <p style={{ fontSize: "12px", opacity: 0.75 }}>
              Optional. If no JSON is uploaded, the chatbot uses
              its existing RAG retrieval pipeline.
            </p>
          </div>

          <div className="section">
            <label>Enter URLs for Web Scraping:</label>
            {urls.map((url, index) => (
              <div key={index} className="url-input-container">
                <input
                  type="text"
                  placeholder={`URL ${index + 1}`}
                  value={url}
                  onChange={(e) => handleUrlChange(index, e.target.value)}
                />
                <button className="remove-btn" onClick={() => removeUrl(index)}>❌</button>
              </div>
            ))}
            <button onClick={addUrlField} className="add-url-btn">+ Add More</button>
          </div>

          <div className="section">
            <label>Chunk Size:</label>
            <input type="number" value={chunkSize} onChange={(e) => setChunkSize(Number(e.target.value))} />
          </div>

          <div className="section">
            <label>Chunk Overlap:</label>
            <input type="number" value={chunkOverlap} onChange={(e) => setChunkOverlap(Number(e.target.value))} />
          </div>

          <div className="section">
            <label>Select Vector Database:</label>
            <select value={selectedVectorDB} onChange={(e) => setSelectedVectorDB(e.target.value)}>
              <option value="">Select Database</option>
              {vectorDBs.map((db) => <option key={db} value={db}>{db}</option>)}
            </select>
          </div>

          <div className="section">
            <label>Select Embedding Model:</label>
            <select value={selectedEmbeddingModel} onChange={(e) => setSelectedEmbeddingModel(e.target.value)}>
              <option value="">Select Model</option>
              {embeddingModels.map((model) => <option key={model} value={model}>{model}</option>)}
            </select>
          </div>

          <button onClick={handlePreprocessing} disabled={isProcessing}>
            {isProcessing ? "Processing..." : "Start Preprocessing"}
          </button>
        </>
      )}

      {isPreprocessed && (
        <>
          <h3 className="preprocessed-message">✅ Preprocessing completed!</h3>

          <div className="section">
            <label>Custom Prompt Template (Optional):</label>
            <textarea
              value={customPrompt}
              onChange={(e) => setCustomPrompt(e.target.value)}
              rows={10}
              placeholder="Enter a custom prompt template here..."
              style={{ width: "100%", fontFamily: "monospace" }}
            />
          </div>

          <div className="section">
            <label>Initial Bot Message:</label>
            <input
              type="text"
              value={initialBotMessage}
              onChange={(e) => setInitialBotMessage(e.target.value)}
              placeholder="Enter welcome message"
              style={{ width: "100%" }}
            />
          </div>

          <div className="section">
            <label>Chatbot Title:</label>
            <input
              type="text"
              value={chatbotTitle}
              onChange={(e) => setChatbotTitle(e.target.value)}
              placeholder="Enter Chatbot Title"
              style={{ width: "100%" }}
            />
          </div>

          {/* NEW: Quick Questions section — each box becomes a clickable chip in the chatbot;
              clicking one sends its text as a normal chat message. */}
          <div className="section">
            <label>Quick Questions (shown as clickable buttons in chat):</label>
            {quickQuestions.map((q, index) => (
              <div key={index} className="url-input-container">
                <input
                  type="text"
                  placeholder={`Quick question ${index + 1}`}
                  value={q}
                  onChange={(e) => handleQuickQuestionChange(index, e.target.value)}
                  style={{ width: "100%" }}
                />
                <button className="remove-btn" onClick={() => removeQuickQuestion(index)}>❌</button>
              </div>
            ))}
            <button onClick={addQuickQuestionField} className="add-url-btn">+ Add Question</button>
          </div>

          <div className="section">
            <label>Max Output Tokens:</label>
            <input
              type="number"
              min={1}
              max={4096}
              value={maxOutputTokens}
              onChange={(e) => setMaxOutputTokens(Number(e.target.value))}
              placeholder="1024"
            />
          </div>

          <div className="section">
            <label>Top K Results (top_k):</label>
            <input
              type="number"
              min={1}
              max={50}
              value={topK}
              onChange={(e) => setTopK(Number(e.target.value))}
              placeholder="Enter number of top chunks to retrieve"
            />
          </div>

          <div className="section">
            <label>Temperature:</label>
            <input
              type="number"
              step={0.01}
              min={0}
              max={1}
              value={temperature}
              onChange={(e) => setTemperature(Number(e.target.value))}
              placeholder="Enter temperature for randomness"
            />
          </div>

          <div className="section">
            <label>Select Chat Model:</label>
            <select value={selectedChatModel} onChange={(e) => setSelectedChatModel(e.target.value)}>
              <option value="">Select Chat Model</option>
              {chatModels.map((model) => <option key={model} value={model}>{model}</option>)}
            </select>
          </div>

          <button
            onClick={handleFinalConfiguration}
            disabled={!selectedChatModel}
            style={{ opacity: !selectedChatModel ? 0.5 : 1, cursor: !selectedChatModel ? "not-allowed" : "pointer" }}
          >
            Run Chatbot
          </button>
        </>
      )}

      {notification && <div className="fade-message">{notification}</div>}
    </div>
  );
};

export default DeveloperConsole;