import seraAvatar from "./sera-avatar.png";


const MAX_INPUT_WORDS = 50;

const wordCount = (value) => (value.trim().match(/\S+/g) || []).length;

const formatTime = (s) =>
  `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

const formatTimestamp = (d) =>
  d.toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });

const URL_SPLIT_REGEX = /(https?:\/\/[^\s]+)/g;
const IS_URL_REGEX = /^https?:\/\//;

// Render Markdown tables safely as React elements.
const splitTableCells = (line) => {
  const value = line.trim().replace(/^\|/, "").replace(/\|$/, "");
  return value
    .split(/(?<!\\)\|/)
    .map((cell) => cell.replace(/\\\|/g, "|").trim());
};

const isTableDivider = (line) => {
  const cells = splitTableCells(line);
  return cells.length > 0 &&
    cells.every((cell) => /^:?-{3,}:?$/.test(cell));
};

const renderRichAnswer = (text, linkify) => {
  const lines = text.split(/\r?\n/);
  const blocks = [];
  let paragraph = [];

  const flush = () => {
    if (paragraph.length) {
      blocks.push(
        <div className="chat-text-block" key={`p-${blocks.length}`}>
          {linkify(paragraph.join("\n"))}
        </div>
      );
      paragraph = [];
    }
  };

  // Convert numbered instructions into the reference-style vertical timeline.
  // Supports plain titles, Markdown bold titles, and descriptions on following lines.
  const parseStep = (line) => {
    const match = line.match(/^\s*(\d{1,2})[.)]\s+(.+?)\s*$/);
    if (!match) return null;
    const raw = match[2].trim();
    const bold = raw.match(/^\*\*(.+?)\*\*\s*(.*)$/);
    return {
      number: Number(match[1]),
      title: (bold ? bold[1] : raw).replace(/\*\*/g, "").trim(),
      description: bold ? bold[2].replace(/^[:\-–—]\s*/, "").trim() : ""
    };
  };

  for (let i = 0; i < lines.length; i++) {
    const first = parseStep(lines[i]);
    if (first && first.number === 1) {
      const steps = [];
      let cursor = i;
      while (cursor < lines.length) {
        const step = parseStep(lines[cursor]);
        if (!step || step.number !== steps.length + 1) break;
        cursor++;
        const description = step.description ? [step.description] : [];
        while (cursor < lines.length) {
          const line = lines[cursor].trim();
          if (parseStep(line) || /^#{1,6}\s/.test(line) ||
              (cursor + 1 < lines.length && line.includes("|") && isTableDivider(lines[cursor + 1]))) break;
          if (!line) {
            const next = (lines[cursor + 1] || "").trim();
            if (!next) { cursor++; break; }
            if (/^(?:Note:|Important:|Please |For more|The specific)/i.test(next)) {
              cursor++;
              break;
            }
          } else {
            description.push(line);
          }
          cursor++;
        }
        steps.push({ ...step, description: description.join(" ").trim() });
        // Skip blank separators between numbered steps.
        while (cursor < lines.length && !lines[cursor].trim()) cursor++;
        if (!parseStep(lines[cursor] || "")) break;
      }
      if (steps.length >= 2) {
        flush();
        blocks.push(
          <div className="auro-steps-timeline" key={`steps-${blocks.length}`}>
            {steps.map((step) => (
              <div className="auro-step" key={step.number}>
                <div className="auro-step-marker" aria-label={`Step ${step.number}`}>{step.number}</div>
                <div className="auro-step-content">
                  <div className="auro-step-title">{step.title}</div>
                  {step.description && <div className="auro-step-description">{step.description}</div>}
                </div>
              </div>
            ))}
          </div>
        );
        i = cursor - 1;
        continue;
      }
    }

    if (
      i + 1 < lines.length &&
      lines[i].includes("|") &&
      isTableDivider(lines[i + 1])
    ) {
      const headers = splitTableCells(lines[i]);
      const divider = splitTableCells(lines[i + 1]);

      if (headers.length >= 2 && headers.length === divider.length) {
        flush();

        const aligns = divider.map((cell) =>
          cell.startsWith(":") && cell.endsWith(":")
            ? "center"
            : cell.endsWith(":")
              ? "right"
              : "left"
        );

        const rows = [];
        i += 2;

        while (i < lines.length && lines[i].trim() && lines[i].includes("|")) {
          const cells = splitTableCells(lines[i]);
          if (cells.length !== headers.length) break;
          rows.push(cells);
          i++;
        }
        i--;

        blocks.push(
          <div
            className="chat-table-scroll"
            role="region"
            aria-label="Chatbot response table"
            tabIndex={0}
            key={`t-${blocks.length}`}
          >
            <table className="chat-response-table">
              <thead>
                <tr>
                  {headers.map((header, j) => (
                    <th
                      key={j}
                      scope="col"
                      style={{ textAlign: aligns[j] }}
                    >
                      {linkify(header)}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {rows.map((row, ri) => (
                  <tr key={ri}>
                    {row.map((cell, ci) => (
                      <td
                        key={ci}
                        style={{ textAlign: aligns[ci] }}
                      >
                        {linkify(cell)}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );
        continue;
      }
    }

    paragraph.push(lines[i]);
  }

  flush();
  return blocks;
};

// URLs are displayed exclusively in the Related panel, never in chat bubbles.
const extractRelatedUrls = (value = "") => Array.from(new Set(
  (String(value).match(/https?:\/\/[^\s)\]<>]+/g) || [])
    .map((url) => url.replace(/[.,;!?]+$/, ""))
));
const cleanAnswer = (value = "") => String(value)
  .replace(/(?:^|\n)\s*(?:Sources|Related Search Results)\s*:[\s\S]*$/i, "")
  .replace(/https?:\/\/[^\s)\]<>]+/g, "")
  .replace(/\n[ \t]*\n[ \t]*\n/g, "\n\n")
  .trim();
const speechText = (value = "") => cleanAnswer(value)
  .replace(/\|/g, ", ").replace(/[*_#`~]/g, "")
  .replace(/\s+/g, " ").trim();
const renderMessageText = (value) => renderRichAnswer(cleanAnswer(value), (part) => part);

function Chatbot({ config = {} }) {
  const projectName = window.location.hostname
    .replace(/^www\./, "")
    .toLowerCase();

  const DEFAULT_CONFIG = {
    API_BASE_URL: "https://api.genaitechsol.shop",
    PROJECT_NAME: projectName,
  };

  const FINAL_CONFIG = { ...DEFAULT_CONFIG, ...config };

  const [headerTarget, setHeaderTarget] = useState(null);

  // Mount the launcher in the host site's navigation if configured.
  useEffect(() => {
    if (!config.HEADER_SELECTOR) {
      setHeaderTarget(null);
      return;
    }

    const locate = () => {
      try {
        setHeaderTarget(
          document.querySelector(config.HEADER_SELECTOR)
        );
      } catch (error) {
        console.warn(
          "[gts-chatbot] Invalid HEADER_SELECTOR:",
          error
        );
        setHeaderTarget(null);
      }
    };

    locate();

    const observer = new MutationObserver(locate);
    observer.observe(document.body, {
      childList: true,
      subtree: true,
    });

    return () => observer.disconnect();
  }, [config.HEADER_SELECTOR]);



  const [ui, setUI] = useState({
    isOpen: false,
    showSettings: false,
    showDeveloperConsole: false,
    showSettingsIcon: false,
    notification: "",
    isRecording: false,
    isMuted: false,
    isBotResponding: false,
    isLoading: false,
  });

  const [adminKey, setAdminKey] = useState("");
  const [accessGranted, setAccessGranted] = useState(false);
  const [call, setCall] = useState({
    modal: false,
    state: "idle",
    time: 0,
  });

  const [chat, setChat] = useState({
    title: config.BOT_NAME || "AUra✦",
    messages: [],
    input: "",
    speakingIndex: null,
  });

  const logoClicksRef = useRef([]);
  const [sideTab, setSideTab] = useState("related");
  const [relatedUrls, setRelatedUrls] = useState([]);
  const [recentQuestions, setRecentQuestions] = useState([]);
  const [expanded, setExpanded] = useState(false);
  const [confirmClear, setConfirmClear] = useState(false);

  const [initialBotMessage, setInitialBotMessage] = useState(
    "Hello! 👋 How can I help you today?"
  );

  const [unreadCount, setUnreadCount] = useState(0);
  const [inputWarning, setInputWarning] = useState(false);
  const [quickQuestions, setQuickQuestions] = useState([]);

  const conversationIdRef = useRef(
    typeof crypto !== "undefined" && crypto.randomUUID
      ? crypto.randomUUID()
      : `chat-${Date.now()}-${Math.random().toString(36).slice(2)}`
  );

  const timerRef = useRef(null);
  const recognitionRef = useRef(null);
  const inputRecordingHeldRef = useRef(false);
  const chatBodyRef = useRef(null);
  const lastQuestionRef = useRef(null);
  const isSpeakingRef = useRef(false);
  const isRecognitionActiveRef = useRef(false);
  const isOpenRef = useRef(false);

  useEffect(() => {
    isOpenRef.current = ui.isOpen;
    if (ui.isOpen) setUnreadCount(0);
  }, [ui.isOpen]);

  const mapLangCodeToLocale = (langCode) =>
    langCode.startsWith("hi") ? "hi-IN" : "en-IN";

  const showMessage = (msg, duration = 3000) => {
    setUI((s) => ({ ...s, notification: msg }));
    setTimeout(
      () => setUI((s) => ({ ...s, notification: "" })),
      duration
    );
  };

  const toggleChatbot = () =>
    setUI((s) => ({
      ...s,
      isOpen: !s.isOpen,
      showSettings: false,
      showDeveloperConsole: false,
      showSettingsIcon: false,
    }));

  const startTimer = () => {
    clearInterval(timerRef.current);
    timerRef.current = setInterval(
      () => setCall((c) => ({ ...c, time: c.time + 1 })),
      1000
    );
  };

  const stopTimer = () => {
    clearInterval(timerRef.current);
  };

  const languageRef = useRef("en-US");
  const callStateRef = useRef(call.state);

  useEffect(() => {
    callStateRef.current = call.state;
  }, [call.state]);

  const addBotMessage = (text) => {
    setRelatedUrls(extractRelatedUrls(text));
    setChat((c) => ({
      ...c,
      messages: [
        ...c.messages,
        { text, sender: "bot", timestamp: new Date() },
      ],
    }));

    if (!isOpenRef.current) {
      setUnreadCount((count) => count + 1);
    }
  };

  const speakAnswer = async (text, language, onComplete) => {
    const synth = window.speechSynthesis;

    const loadVoices = () =>
      new Promise((resolve) => {
        let voices = synth.getVoices();
        if (voices.length) return resolve(voices);

        const interval = setInterval(() => {
          voices = synth.getVoices();
          if (voices.length) {
            clearInterval(interval);
            resolve(voices);
          }
        }, 200);
      });

    const voices = await loadVoices();

    const langLocale = language.toLowerCase().startsWith("hi")
      ? "hi-IN"
      : "en-IN";

    const preferredVoices = {
      "en-IN": ["Lekha"],
      "hi-IN": ["Google हिन्दी", "Lekha"],
    };

    const voice =
      voices.find((v) =>
        preferredVoices[langLocale]?.includes(v.name)
      ) ||
      voices.find(
        (v) =>
          v.lang === langLocale &&
          v.name.toLowerCase().includes("female")
      ) ||
      voices.find((v) => v.lang === langLocale) ||
      voices[0];

    const utterance = new SpeechSynthesisUtterance(speechText(text));
    utterance.lang = langLocale;
    utterance.voice = voice;
    utterance.rate = 0.92;
    utterance.pitch = 1;
    utterance.volume = 1;

    isSpeakingRef.current = true;

    utterance.onend = () => {
      isSpeakingRef.current = false;
      setTimeout(() => onComplete?.(), 1000);
    };

    synth.cancel();
    synth.speak(utterance);
  };

  function startInputRecording() {
    const rec = recognitionRef.current;

    if (!rec) {
      showMessage(
        "Speech recognition is not supported in this browser."
      );
      return;
    }

    if (inputRecordingHeldRef.current) return;

    inputRecordingHeldRef.current = true;
    rec.continuous = true;
    rec.interimResults = true;
    rec.lang = "en-IN";

    let finalTranscript = "";

    rec.onresult = (event) => {
      let interimTranscript = "";

      for (
        let i = event.resultIndex;
        i < event.results.length;
        i++
      ) {
        const transcript = event.results[i][0].transcript;

        if (event.results[i].isFinal) {
          finalTranscript += transcript;
        } else {
          interimTranscript += transcript;
        }
      }

      setChat((c) => ({
        ...c,
        input: finalTranscript + interimTranscript,
      }));
    };

    rec.onerror = (error) => {
      inputRecordingHeldRef.current = false;
      console.error("Recognition error:", error);
      setUI((u) => ({ ...u, isRecording: false }));
    };

    rec.onend = () => {
      inputRecordingHeldRef.current = false;
      setUI((u) => ({ ...u, isRecording: false }));
    };

    try {
      rec.start();
      setUI((u) => ({ ...u, isRecording: true }));
    } catch (error) {
      inputRecordingHeldRef.current = false;
      console.error("Microphone error:", error);
    }
  }

  const stopInputRecording = () => {
    if (!inputRecordingHeldRef.current) return;

    inputRecordingHeldRef.current = false;

    try {
      recognitionRef.current?.stop();
    } catch (error) {
      console.warn("Microphone stop:", error);
    }

    setUI((u) => ({ ...u, isRecording: false }));
  };

  const handleCallQuery = async (query) => {
    return new Promise(async (resolve) => {
      try {
        const response = await fetch(
          `${FINAL_CONFIG.API_BASE_URL}/chat`,
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              query,
              project_name: FINAL_CONFIG.PROJECT_NAME,
              conversation_id: conversationIdRef.current,
            }),
          }
        );

        const data = await response.json();

        const answer = response.ok
          ? data.response
          : "Sorry, I couldn't understand that.";

        const detectedLang = response.ok
          ? data.language
          : "en";

        languageRef.current =
          mapLangCodeToLocale(detectedLang);

        setChat((c) => ({
          ...c,
          messages: [
            ...c.messages,
            {
              text: query,
              sender: "user",
              timestamp: new Date(),
            },
          ],
        }));

        addBotMessage(answer);
        speakAnswer(answer, detectedLang, resolve);
      } catch (error) {
        console.error("Chat fetch error:", error);
        addBotMessage("Something went wrong.");
        speakAnswer("Something went wrong.", "en", resolve);
      }
    });
  };

  const startCallListening = () => {
    const rec = recognitionRef.current;

    if (!rec) return;
    if (isSpeakingRef.current) return;
    if (isRecognitionActiveRef.current) return;

    rec.continuous = false;
    rec.interimResults = false;
    rec.lang = languageRef.current || "en-IN";

    rec.onstart = () => {
      isRecognitionActiveRef.current = true;
    };

    rec.onend = () => {
      isRecognitionActiveRef.current = false;

      if (callStateRef.current !== "active") return;

      const retry = () => {
        if (!isSpeakingRef.current) {
          startCallListening();
        } else {
          setTimeout(retry, 1000);
        }
      };

      setTimeout(retry, 500);
    };

    rec.onerror = (error) => {
      isRecognitionActiveRef.current = false;
      console.error("Recognition error:", error);

      if (callStateRef.current === "active") {
        setTimeout(startCallListening, 500);
      }
    };

    rec.onresult = (event) => {
      if (isSpeakingRef.current) return;

      const transcript =
        event.results[0][0].transcript.trim();

      handleCallQuery(transcript).then(() => {
        if (callStateRef.current === "active") {
          startCallListening();
        }
      });
    };

    try {
      rec.start();
    } catch (error) {
      console.error("Failed to start recognition:", error);
    }
  };

  const handleSpeak = (text, idx) => {
    if (!("speechSynthesis" in window)) { showMessage("Voice playback is unavailable in this browser."); return; }
    const synth = window.speechSynthesis;
    synth.cancel();
    const utterance = new SpeechSynthesisUtterance(speechText(text));
    const voices = synth.getVoices();
    const locale = /[\u0900-\u097F]/.test(text) ? "hi-IN" : "en-IN";
    const matching = voices.filter((v) => v.lang.toLowerCase().startsWith(locale.slice(0, 2)));
    const preferred = matching.find((v) => /premium|enhanced|natural|lekha|google|samantha/i.test(v.name));
    utterance.voice = preferred || matching[0] || null;
    utterance.lang = utterance.voice?.lang || locale;
    utterance.rate = 0.9;
    utterance.pitch = 1;
    utterance.volume = 1;
    utterance.onend = () => setChat((c) => ({ ...c, speakingIndex: null }));
    utterance.onerror = () => setChat((c) => ({ ...c, speakingIndex: null }));
    setChat((c) => ({ ...c, speakingIndex: idx }));
    synth.speak(utterance);
  };

  const handlePause = () => {
    window.speechSynthesis.cancel();
    setChat((c) => ({ ...c, speakingIndex: null }));
  };

  const fetchConfig = async () => {
    try {
      const response = await fetch(
        `${FINAL_CONFIG.API_BASE_URL}/get_config?project_name=${encodeURIComponent(FINAL_CONFIG.PROJECT_NAME)}`
      );

      if (!response.ok) {
        throw new Error("Unable to load chatbot configuration");
      }

      const cfg = await response.json();

const msg = cfg.initial_message || initialBotMessage;
      const title = cfg.chatbot_title?.trim() || FINAL_CONFIG.BOT_NAME || "AUra✦";

      setInitialBotMessage(msg);
      setRelatedUrls([]);

      setChat((c) => ({
        ...c,
        title,
        messages: [
          {
            text: msg,
            sender: "bot",
            timestamp: new Date(),
          },
        ],
      }));

      setQuickQuestions(
        Array.isArray(cfg.quick_questions)
          ? cfg.quick_questions
          : []
      );

      setUnreadCount(isOpenRef.current ? 0 : 1);
    } catch (error) {
      const fallback =
        "Hello! 👋 How can I help you today?";

      setInitialBotMessage(fallback);

      setChat((c) => ({
        ...c,
        messages: [
          {
            text: fallback,
            sender: "bot",
            timestamp: new Date(),
          },
        ],
      }));

      setQuickQuestions([]);
      setUnreadCount(isOpenRef.current ? 0 : 1);
    }
  };

  const handleSendMessage = async (overrideText) => {
    const submitted = (typeof overrideText === "string" ? overrideText : chat.input).trim();
    if (submitted && !ui.isBotResponding) setRecentQuestions((prev) => [submitted, ...prev.filter((q) => q !== submitted)].slice(0, 30));
    const text = (
      typeof overrideText === "string"
        ? overrideText
        : chat.input
    ).trim();

    if (!text || ui.isBotResponding) return;

    if (wordCount(text) > MAX_INPUT_WORDS) {
      setInputWarning(true);
      showMessage("Maximum 50 words per message.");
      return;
    }

    setInputWarning(false);

    const userMsg = {
      text,
      sender: "user",
      timestamp: new Date(),
    };

    setRelatedUrls([]);
    setSideTab("related");
    setChat((c) => ({
      ...c,
      input: "",
      messages: [...c.messages, userMsg],
    }));

    setUI((u) => ({
      ...u,
      isBotResponding: true,
      isLoading: true,
    }));

    try {
      const response = await fetch(
        `${FINAL_CONFIG.API_BASE_URL}/chat`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            query: userMsg.text,
            project_name: FINAL_CONFIG.PROJECT_NAME,
            conversation_id: conversationIdRef.current,
          }),
        }
      );

      const data = await response.json();

      const botText = response.ok
        ? data.response
        : `Error: ${data.detail}`;

      addBotMessage(botText);
    } catch (error) {
      addBotMessage("Error connecting to server.");
    } finally {
      setUI((u) => ({
        ...u,
        isBotResponding: false,
        isLoading: false,
      }));
    }
  };

  const handleQuickQuestionClick = (question) => {
    handleSendMessage(question);
  };

  const handleCopy = async (text) => {
    try {
      await navigator.clipboard.writeText(text);
      showMessage("Copied to clipboard!");
    } catch (error) {
      console.error("Failed to copy:", error);
    }
  };

  useEffect(() => {
    const SpeechRecognition =
      window.SpeechRecognition ||
      window.webkitSpeechRecognition;

    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
    }

    fetchConfig();
  }, []);

  const latestUserMessageIndex = chat.messages.reduce(
    (last, message, index) =>
      message.sender === "user" ? index : last,
    -1
  );

  useEffect(() => {
    if (!ui.isOpen || ui.showDeveloperConsole) return;

    const frame = requestAnimationFrame(() => {
      const body = chatBodyRef.current;
      if (!body) return;

      const question = lastQuestionRef.current;

      if (question) {
        const bodyTop =
          body.getBoundingClientRect().top;

        const questionTop =
          question.getBoundingClientRect().top;

        body.scrollTop += questionTop - bodyTop - 12;
      } else {
        body.scrollTop = body.scrollHeight;
      }
    });

    return () => cancelAnimationFrame(frame);
  }, [
    ui.isOpen,
    ui.showDeveloperConsole,
    latestUserMessageIndex,
  ]);

  const renderBotControls = (msg, idx) => (
    <span
      style={{
        display: "flex",
        alignItems: "center",
        gap: "8px",
      }}
    >
      {chat.speakingIndex === idx ? (
        <IoPause
          onClick={handlePause}
          size={16}
          style={{ cursor: "pointer", color: "white" }}
        />
      ) : (
        <IoVolumeHigh
          onClick={() => handleSpeak(msg.text, idx)}
          size={16}
          style={{ cursor: "pointer", color: "white" }}
        />
      )}

      <MdContentCopy
        onClick={() => handleCopy(msg.text)}
        size={16}
        style={{ cursor: "pointer", color: "white" }}
      />
    </span>
  );

  const botName = chat.title || FINAL_CONFIG.BOT_NAME || "AUra✦";
  const hasConversation = chat.messages.some((m) => m.sender === "user");
  const clearHistory = () => {
    window.speechSynthesis?.cancel();
    conversationIdRef.current = typeof crypto !== "undefined" && crypto.randomUUID
      ? crypto.randomUUID() : `chat-${Date.now()}`;
    setChat((c) => ({ ...c, messages: [{ text: initialBotMessage, sender: "bot", timestamp: new Date() }], input: "", speakingIndex: null }));
    setRecentQuestions([]);
    setRelatedUrls([]);
    setSideTab("related");
    setConfirmClear(false);
    showMessage("Conversation cleared");
  };
  const leaveVoicePage = () => {
    try { recognitionRef.current?.stop(); } catch (_) {}
    window.speechSynthesis?.cancel();
    isSpeakingRef.current = false;
    stopTimer();
    setCall({ modal: false, state: "idle", time: 0 });
  };
  const onLogoClick = () => {
    const now = Date.now();
    logoClicksRef.current = [...logoClicksRef.current.filter((t) => now - t < 2000), now];
    if (logoClicksRef.current.length >= 4) {
      logoClicksRef.current = [];
      setUI((s) => ({ ...s, showSettings: true }));
    }
  };
  // Launcher uses the configured assistant name.
  const launcher = (
    <button
      type="button"
      className="auro-search-launcher"
      onClick={toggleChatbot}
      aria-label={`Open Ask ${botName} chatbot`}
      aria-expanded={ui.isOpen}
    >
      <span
        className="auro-search-symbol"
        aria-hidden="true"
      >
        ✺
      </span>

      <span className="auro-search-label">
        {config.LAUNCHER_TEXT || `Ask ${botName}`}
      </span>

      <IoMic
        className="auro-search-mic"
        aria-hidden="true"
      />


    </button>
  );

  return (
    <div
      className="chatbot-container"

    >
      
{!ui.isOpen && (
  headerTarget
    ? createPortal(launcher, headerTarget)
    : launcher
)}


      {ui.isOpen && (
        <div className="auro-overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) toggleChatbot(); }}>
        <div className={`chatbox auro-panel ${expanded ? "auro-expanded" : ""} ${!hasConversation && !ui.showDeveloperConsole ? "auro-welcome-mode" : ""}`} role="dialog" aria-modal="true" aria-label={`${botName} assistant`}>
          <div className="chat-header">
            <div className="auro-heading">
              <button type="button" className="auro-logo" onClick={onLogoClick} aria-label="Assistant logo">✺</button>
              <div><strong>Hi, I’m {botName}. How can I help?</strong><small>Ask about accounts, deposits, cards, loans or offers</small></div>
            </div>
            <div className="icons">
              <button type="button" className="auro-icon-btn" onClick={() => setConfirmClear(true)} title="Clear conversation" aria-label="Clear conversation"><AiOutlineReload /></button>
              <button type="button" className="auro-icon-btn" onClick={() => setExpanded((v) => !v)} title="Toggle size">⛶</button>
              <button type="button" className="auro-icon-btn" onClick={toggleChatbot} aria-label="Close"><IoClose /></button>
            </div>
          </div>
          {confirmClear && <div className="auro-confirm-clear" role="alertdialog" aria-label="Clear conversation"><span>Clear this conversation and start fresh?</span><button type="button" onClick={clearHistory}>Clear history</button><button type="button" onClick={() => setConfirmClear(false)}>Cancel</button></div>}
          {!hasConversation && !ui.showDeveloperConsole && <div className="auro-hero"><button className="auro-logo auro-logo-large" type="button" onClick={onLogoClick}>✺</button><h1>Hi, I’m {botName}</h1><p>How Can I Help You Today?</p></div>}
          <div className="auro-content">
          <div className="auro-main">
          <div
            className="chat-body"
            ref={chatBodyRef}
          >
            {ui.showDeveloperConsole ? (
              <DeveloperConsole
                config={config}
                closeConsole={() => {
                  setAccessGranted(false);

                  setUI((u) => ({
                    ...u,
                    showDeveloperConsole: false,
                  }));

                  fetchConfig();
                }}
                openChatbot={() =>
                  setUI((u) => ({
                    ...u,
                    isOpen: true,
                  }))
                }
              />
            ) : (
              <>
                {(hasConversation ? chat.messages : []).map((message, i) => (
                  <div
                    key={i}
                    ref={
                      i === latestUserMessageIndex
                        ? lastQuestionRef
                        : null
                    }
                    className={
                      message.sender === "bot"
                        ? `bot-message${
                            /\n\s*\|?.+\|.+\n\s*\|?\s*:?-{3,}/.test(
                              message.text || ""
                            )
                              ? " bot-message-with-table"
                              : ""
                          }`
                        : "user-message"
                    }
                  >
                    <div className="message-content">
                      {renderMessageText(message.text)}
                    </div>

                    <div className="message-meta">
                      <span className="timestamp">
                        {formatTimestamp(
                          new Date(message.timestamp)
                        )}
                      </span>

                      {message.sender === "bot" &&
                        renderBotControls(message, i)}
                    </div>
                  </div>
                ))}

                {ui.isLoading && (
                  <div className="bot-message thinking-icon">
                    <span className="dot one"></span>
                    <span className="dot two"></span>
                    <span className="dot three"></span>
                  </div>
                )}
              </>
            )}
          </div>

          {call.modal && (
            <div className="call-ui">
              <div
                className="call-header"
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: "0 10px",
                }}
              >
                <IoClose
                  size={24}
                  style={{ cursor: "pointer" }}
                  onClick={leaveVoicePage}
                />

                <span
                  style={{
                    flex: 1,
                    textAlign: "center",
                    fontWeight: "bold",
                    fontSize: "18px",
                  }}
                >
                  {botName} Voice Assistant
                </span>

                <div style={{ width: "24px" }}></div>
              </div>

              <button type="button" className="auro-voice-back" onClick={leaveVoicePage}>← Back to Chat</button>
              <div className="call-content">
                <div className="auro-voice-eyebrow"><span className="auro-live-dot" /> VOICE EXPERIENCE</div>
                <img
                  src={seraAvatar}
                  alt={`${botName} AI Voice Assistant`}
                  className="call-avatar"
                />

                <h2 className="agent-name">
                  {botName} <span className="ai-badge">AI</span>
                </h2>

                <p className="auro-voice-subtitle">Your personal banking assistant, ready to listen.</p>
                <div className="auro-voice-bars" aria-hidden="true">{Array.from({length: 19}, (_, i) => <i key={i} style={{animationDelay: `${i * 75}ms`}} />)}</div>

                {call.state === "idle" && (
                  <button
                    className="talk-button"
                    onClick={() => {
                      setCall({
                        modal: true,
                        state: "active",
                        time: 0,
                      });

                      speakAnswer(
                        `Hello, my name is ${botName}. How can I assist you today?`,
                        "en",
                        () => {
                          startCallListening();
                          startTimer();
                        }
                      );
                    }}
                  >
                    <MdGraphicEq
                      size={20}
                      className="talk-button-icon"
                    />
                    Talk to {botName}
                  </button>
                )}

                {call.state === "active" && (
                  <>
                    <p className="listening-text">
                      Listening to you...
                    </p>

                    <p
                      style={{
                        color: "#ccc",
                        marginTop: "4px",
                      }}
                    >
                      {formatTime(call.time)}
                    </p>

                    <div className="call-control-buttons">
                      <button
                        className="mute-call-button"
                        onClick={() =>
                          setUI((u) => ({
                            ...u,
                            isMuted: !u.isMuted,
                          }))
                        }
                      >
                        {ui.isMuted ? (
                          <IoMicOff size={24} />
                        ) : (
                          <IoMic size={24} />
                        )}
                      </button>

                      <button
                        className="end-call-button"
                        onClick={() => {
                          recognitionRef.current?.stop();
                          window.speechSynthesis.cancel();

                          setCall((c) => ({
                            ...c,
                            state: "ended",
                          }));

                          stopTimer();
                        }}
                      >
                        <IoClose size={24} />
                      </button>
                    </div>

                    <div className="call-control-labels">
                      <span>
                        {ui.isMuted ? "Unmute" : "Mute"}
                      </span>
                      <span>End Call</span>
                    </div>
                  </>
                )}

                {call.state === "ended" && (
                  <>
                    <div className="call-ended-section">
                      <MdPhoneDisabled size={20} />
                      <span className="call-ended-text">
                        Call Ended
                      </span>
                      <span className="call-time">
                        {formatTime(call.time)}
                      </span>
                    </div>

                    <div className="call-ended-buttons">
                      <button
                        onClick={() => {
                          setCall({
                            modal: true,
                            state: "active",
                            time: 0,
                          });

                          speakAnswer(
                            "Welcome back. How can I help you again?",
                            "en",
                            () => {
                              startTimer();
                              startCallListening();
                            }
                          );
                        }}
                      >
                        <IoCall size={18} />
                        Call Again
                      </button>

                      <button
                        onClick={() =>
                          setCall((c) => ({
                            ...c,
                            modal: false,
                          }))
                        }
                      >
                        <IoChatbubble size={18} />
                        Back to Chat
                      </button>
                    </div>
                  </>
                )}
              </div>
            </div>
          )}

          {!ui.showDeveloperConsole && quickQuestions.length > 0 && (
            <div className="auro-marquee" aria-label="Suggested questions"><div className="auro-marquee-track">
              {[...quickQuestions, ...quickQuestions].map((question, i) => (
                <button key={i} type="button" className="quick-question-chip" onClick={() => handleQuickQuestionClick(question)} disabled={ui.isBotResponding || wordCount(question) > MAX_INPUT_WORDS}>{question}</button>
              ))}
            </div></div>
          )}

          {!ui.showDeveloperConsole && (
            <>
              <div className="chat-input-container">
                <input
                  className="chat-input"
                  value={chat.input}
                  placeholder={
                    ui.isBotResponding
                      ? "You can type, but wait..."
                      : "Type or hold mic to speak..."
                  }
                  onChange={(event) => {
                    const value = event.target.value;

                    setInputWarning(
                      wordCount(value) > MAX_INPUT_WORDS
                    );

                    setChat((c) => ({
                      ...c,
                      input: value,
                    }));
                  }}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      event.preventDefault();

                      if (
                        !ui.isBotResponding &&
                        wordCount(chat.input) <= MAX_INPUT_WORDS
                      ) {
                        handleSendMessage();
                      }
                    }
                  }}
                />

                <button
                  className={`mic-button ${
                    ui.isRecording ? "recording" : ""
                  }`}
                  onPointerDown={(event) => {
                    if (
                      event.button !== 0 &&
                      event.pointerType === "mouse"
                    ) {
                      return;
                    }

                    event.preventDefault();

                    event.currentTarget.setPointerCapture?.(
                      event.pointerId
                    );

                    startInputRecording();
                  }}
                  onPointerUp={stopInputRecording}
                  onPointerCancel={stopInputRecording}
                  onLostPointerCapture={stopInputRecording}
                  onContextMenu={(event) =>
                    event.preventDefault()
                  }
                  title="Hold to speak"
                  aria-label="Hold to speak"
                >
                  <IoMic size={22} />
                </button>

                <button
                  className="send-button"
                  onClick={() => handleSendMessage()}
                  disabled={
                    ui.isBotResponding ||
                    !chat.input.trim() ||
                    wordCount(chat.input) > MAX_INPUT_WORDS
                  }
                >
                  <IoSend size={18} />
                </button>
              </div>

              <div
                className="chat-word-count"
                aria-live="polite"
              >
                {inputWarning
                  ? "Maximum 50 words allowed. Please shorten your message. "
                  : ""}
                {wordCount(chat.input)}/50 words
              </div>

              <div className="chat-input-secondary-buttons" aria-label="Voice assistant actions">


                <button
                  className="call-agent-circle-button"
                  onClick={() =>
                    setCall({
                      modal: true,
                      state: "idle",
                      time: 0,
                    })
                  }
                  title={`Open ${botName} voice assistant`}
                  aria-label={`Open ${botName} voice assistant`}
                >
                  <MdGraphicEq size={21} />
                  <span>Voice Assistant</span>
                  <span className="auro-voice-arrow"></span>
                </button>
              </div>
            </>
          )}

          </div>
          {(hasConversation && !ui.showDeveloperConsole) && <aside className="auro-sidebar">
            <div className="auro-tabs"><button className={sideTab === "related" ? "active" : ""} onClick={() => setSideTab("related")}>Related</button><button className={sideTab === "recent" ? "active" : ""} onClick={() => setSideTab("recent")}>Recent</button></div>
            {sideTab === "related" ? <div className="auro-sidebar-items">{relatedUrls.length ? relatedUrls.map((url,i) => <a className="auro-side-card" key={i} href={url} target="_blank" rel="noopener noreferrer"><strong>{(() => { try { return new URL(url).pathname.split("/").filter(Boolean).pop()?.replace(/[-_]/g," ") || "AU Bank resource"; } catch { return "Related resource"; } })()}</strong><small>{url}</small><span>Explore ›</span></a>) : <p className="auro-side-empty">Related pages for your latest question will appear here.</p>}</div> : <div className="auro-sidebar-items"><button className="auro-clear" onClick={() => setRecentQuestions([])}>Clear all</button>{recentQuestions.map((q,i) => <div className="auro-recent-item" key={i}><button onClick={() => handleQuickQuestionClick(q)}>{q}</button><button aria-label="Remove recent question" onClick={() => setRecentQuestions((prev) => prev.filter((_,j) => i !== j))}>×</button></div>)}</div>}
          </aside>}
          </div>
          {ui.showSettings && (
            <div className="admin-modal">
              <div className="admin-modal-content">
                <div className="admin-header">
                  <h3>Enter Admin Key</h3>

                  <IoClose
                    className="close-icon"
                    onClick={() =>
                      setUI((u) => ({
                        ...u,
                        showSettings: false,
                      }))
                    }
                  />
                </div>

                <input
                  type="password"
                  value={adminKey}
                  onChange={(event) =>
                    setAdminKey(event.target.value)
                  }
                  className="admin-input"
                  placeholder="Enter admin key"
                />

                <button
                  className="admin-submit"
                  onClick={() => {
                    if (adminKey === "admin123") {
                      setAccessGranted(true);

                      setUI((u) => ({
                        ...u,
                        showSettings: false,
                        showDeveloperConsole: true,
                      }));
                    } else {
                      showMessage("Incorrect Admin Key!");
                    }
                  }}
                >
                  Submit
                </button>
              </div>
            </div>
          )}

          {ui.notification && (
            <div className="fade-message">
              {ui.notification}
            </div>
          )}
        </div>
        </div>
      )}
    </div>
  );
}

export default Chatbot;